mapper.select:
SELECT (MIN(l.changed_at)::DATE - d.proposed_date) AS days
  FROM biz_demand d
  JOIN audit_state_log l
    ON l.object_type = #{objectType}
   AND l.object_id = d.id
   AND l.state_field = #{stateField}
   AND l.to_state = #{toState}
 WHERE d.deleted = FALSE
   AND d.proposed_date IS NOT NULL
 GROUP BY d.id, d.proposed_date

SELECT (MIN(l.changed_at)::DATE - c.initiated_date) AS days
  FROM biz_course c
  JOIN audit_state_log l
    ON l.object_type = #{objectType}
   AND l.object_id = c.id
   AND l.state_field = #{stateField}
   AND l.to_state = #{toState}
 WHERE c.deleted = FALSE
   AND c.initiated_date IS NOT NULL
 GROUP BY c.id, c.initiated_date

SELECT COUNT(*)
  FROM biz_course
 WHERE deleted = FALSE
   AND created_at >= #{from}
   AND created_at < #{to}
